//! BQ047 original entry trigger. Closed candidate; clock conversion is separate.
use crate::{catalog,engine::RuleResult,model::*,rules::*};
use std::collections::BTreeSet;
pub(crate) const ID:&str="BQ047";
pub(crate) const KEY:&str="bq047-destroy-and-sacrifice";
fn same<T:serde::Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
pub(crate) fn definition()->Definition{let mut d=with_abilities(vec![ability(KEY,"进场强制：毁灭本地区；本方末日钟时各牺牲四资产",Timing::Fast,vec![],vec![],vec![Op::BQ047Entry],Some(Event::Enter))]);d.traits.kill=1;d}
fn has_op(ops:&[Op])->bool{ops.iter().any(|o|match o{Op::BQ047Entry=>true,Op::ForEachLivingPlayer(v)|Op::ForEachLivingPlayerFromActor(v)=>has_op(v),Op::IfTargetExhausted{exhausted,ready,..}=>has_op(std::slice::from_ref(exhausted))||has_op(std::slice::from_ref(ready)),_=>false})}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("bq047-")||has_op(&a.ops)||a.modes.iter().any(|m|has_op(&m.ops))}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{if id!=ID||!same(a,&definition().abilities[0]){return Err("灭世魔原强制进场程序不可改写".into())}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if(id==ID||d.abilities.iter().any(related))&&(id!=ID||!same(d,&definition())){return Err("灭世魔定义不可移植".into())}Ok(())}
fn owned(f:&ResolutionFrame)->bool{f.ability_key.starts_with("bq047-")||f.steps.iter().any(|s|has_op(std::slice::from_ref(&s.op)))}
impl Game{
 fn bq047_source(&self,actor:usize,s:&SourceSnapshot)->RuleResult<()>{let c=&s.card;if actor>=self.players.len()||c.controller!=actor||c.owner>=self.players.len()||c.definition!=ID||c.face_down||!self.mystic_instance_valid(&c.id)||s.region.is_none_or(|r|r>=self.regions.len())||s.source_region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))||s.play_source.is_some()||s.attachment_host_instance.is_some()||s.death_echo.is_some()||s.observed_death.is_some()||s.observed_exposure.is_some()||s.observed_mobility_grant.is_some(){return Err("灭世魔原进场来源损坏".into())}self.mobility_immutable_identity(c)}
 pub(crate) fn bq047_forced(&mut self,d:&Declaration)->RuleResult<bool>{if d.source.card.definition!=ID&&!related(&d.ability){return Ok(false)}validate_ability(&d.source.card.definition,&d.ability)?;self.bq047_source(d.actor,&d.source)?;if !self.players[d.actor].eliminated{let f=self.make_frame(d.actor,d.source.clone(),&d.ability,vec![],vec![],None);self.dispatch_frame(f,d.ability.label.clone(),None,ResponsePolicy::Respondable);}Ok(true)}
 pub(crate) fn bq047_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if !owned(f){return Ok(())}self.bq047_source(f.actor,&f.source)?;self.validate_resource_frame(f)?;if f.ability_key!=KEY||!self.mystic_instance_valid(&f.frame_id)||f.cursor>1||f.chosen_region.is_some()||!f.targets.is_empty()||!f.already_paid.is_empty()||!same(&f.steps,&vec![Step{context:f.actor,op:Op::BQ047Entry}])||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor==1&&!matches!(f.guard,GuardState::Accepted){return Err("灭世魔帧程序或阶段损坏".into())}Ok(())}
 fn bq047_clock(&self,actor:usize)->bool{self.players[actor].society_zone.card.as_ref().is_some_and(|c|c.definition=="MSJZ03"&&!c.face_down&&c.controller==actor)}
 pub(crate) fn bq047_resolve(&mut self,f:ResolutionFrame)->RuleResult<()>{self.bq047_frame(&f)?;if f.cursor!=1{return Err("灭世魔结算须消费原步骤".into())}if let Some(r)=self.original_region(&f.source){self.regions[r].destroyed=true;}if self.bq047_clock(f.actor){self.bq047_offer(f,vec![])?;}Ok(())}
 fn bq047_options(&self,seat:usize)->Vec<ChoiceOption>{self.players[seat].assets.iter().map(|c|ChoiceOption{id:c.id.clone(),label:format!("{} {}",catalog::card(&c.definition).name,c.id),card:Some(self.card_view(c,seat,None,Some("asset")))}).collect()}
 fn bq047_chosen(&self,chosen:&[Vec<String>])->RuleResult<()>{if chosen.len()>self.players.len(){return Err("灭世魔玩家游标越界".into())}let mut all=BTreeSet::new();for(s,ids)in chosen.iter().enumerate(){let n=if self.players[s].eliminated{0}else{self.players[s].assets.len().min(4)};if ids.len()!=n||ids.iter().any(|id|!all.insert(id)||!self.players[s].assets.iter().any(|c|&c.id==id)){return Err("灭世魔原资产批次损坏".into())}}Ok(())}
 fn bq047_offer(&mut self,f:ResolutionFrame,mut chosen:Vec<Vec<String>>)->RuleResult<()>{self.bq047_chosen(&chosen)?;while chosen.len()<self.players.len(){let s=chosen.len();let opts=self.bq047_options(s);if self.players[s].eliminated||opts.is_empty(){chosen.push(vec![]);continue}let n=opts.len().min(4);self.choice(s,"bq047-assets","灭世魔：选择牺牲的资产".into(),opts,n,n,None,ChoiceResolution::Frame{frame:Box::new(f),choice:FrameChoice::BQ047Assets{chosen}});return Ok(())}for(s,ids)in chosen.into_iter().enumerate(){for id in ids{let i=self.players[s].assets.iter().position(|c|c.id==id).ok_or("原资产离场")?;let c=self.players[s].assets.remove(i);self.note(format!("{}牺牲资产{}",player_id(s),catalog::card(&c.definition).name));let c=self.reset_zone_card(c);self.commit_owner_grave(c,None);}}Ok(())}
 pub(crate) fn bq047_choose(&mut self,f:ResolutionFrame,mut chosen:Vec<Vec<String>>,seat:usize,a:&Action,ids:&[String])->RuleResult<()>{self.bq047_frame(&f)?;self.bq047_chosen(&chosen)?;if f.cursor!=1||seat!=chosen.len()||seat>=self.players.len()||!self.bq047_clock(f.actor)||*a!=(Action{choice_id:a.choice_id.clone(),selected:a.selected.clone(),..Action::new("choose")}){return Err("灭世魔资产选择身份无效".into())}chosen.push(ids.to_vec());self.bq047_chosen(&chosen)?;self.bq047_offer(f,chosen)}
 pub(crate) fn validate_bq047_state(&self)->RuleResult<()>{let mut seen=BTreeSet::new();let mut check=|f:&ResolutionFrame|->RuleResult<()>{self.bq047_frame(f)?;if owned(f)&&!seen.insert(f.frame_id.clone()){return Err("灭世魔同帧重复续体".into())}Ok(())};for i in &self.stack{if let Some(f)=&i.frame{check(f)?;if owned(f)&&(i.card.is_some()||i.id!=f.frame_id||i.controller!=f.actor||i.reveal||i.deploy_region.is_some()||i.target.is_some()||f.cursor!=0){return Err("灭世魔响应外壳损坏".into())}}}for e in &self.effects{match e{Effect::Frame{frame}=>check(frame)?,Effect::Declare{declaration:d}if d.source.card.definition==ID||related(&d.ability)=>{validate_ability(&d.source.card.definition,&d.ability)?;self.bq047_source(d.actor,&d.source)?;},_=>()}}if let Some(p)=&self.pending{match &p.resolution{ChoiceResolution::Frame{frame:f,choice}=>{check(f)?;if owned(f)||matches!(choice,FrameChoice::BQ047Assets{..}){let FrameChoice::BQ047Assets{chosen}=choice else{return Err("灭世魔待选类型错误".into())};self.bq047_chosen(chosen)?;let s=chosen.len();if !owned(f)||f.cursor!=1||s>=self.players.len()||self.players[s].eliminated||!self.bq047_clock(f.actor){return Err("灭世魔资产阶段错误".into())}let opts=self.bq047_options(s);let n=opts.len().min(4);let expected=Choice{id:p.choice.id.clone(),kind:"bq047-assets".into(),title:"灭世魔：选择牺牲的资产".into(),description:"选择符合数量限制的选项，然后确认。".into(),player_id:player_id(s),options:opts,preview_cards:vec![],min:Some(n),max:Some(n),amount:None,allow_decline:Some(false)};if n==0||p.seat!=s||!self.mystic_instance_valid(&p.choice.id)||!same(&p.choice,&expected){return Err("灭世魔选项损坏".into())}}},ChoiceResolution::Declare{declaration:d,..}if d.source.card.definition==ID||related(&d.ability)=>return Err("灭世魔强制触发不可改为可选".into()),_=>()}}Ok(())}
}
